# Check edge cases for sieve and factor
import sys
sys.path.insert(0, '.')
from more_itertools.recipes import sieve, factor

# Test with non-integer inputs
for name, func, arg in [('sieve', sieve, 'abc'), ('factor', factor, 'abc')]:
    try:
        result = list(func(arg))
        print(f"{name}('abc'): {result}")
    except Exception as e:
        print(f"{name}('abc'): {type(e).__name__}: {e}")

# Test with float inputs
for name, func, arg in [('sieve', sieve, 10.5), ('factor', factor, 10.5)]:
